// One API request per keyword. The Jobsuche API searches one term at a time.
const s = $input.first().json;
const keywords = String(s.keywords || '').split(',').map(k => k.trim()).filter(Boolean);
return keywords.map(was => ({
  json: {
    was,
    url: 'https://rest.arbeitsagentur.de/jobboerse/jobsuche-service/pc/v6/jobs'
      + '?was=' + encodeURIComponent(was)
      + '&wo=' + encodeURIComponent(s.location)
      + '&umkreis=' + Number(s.radiusKm || 25)
      + '&size=100',
  },
}));

// Merge all responses, drop old/excluded/already-sent postings, rank the rest.
const s = $('Search settings').first().json;
const queries = $('Build queries').all().map(i => i.json.was);
const exclude = String(s.excludeWords || '').split(',').map(w => w.trim()).filter(Boolean);
const excludeRe = exclude.length ? new RegExp(exclude.map(w => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|'), 'i') : null;
const cutoff = Date.now() - Number(s.maxAgeDays || 3) * 864e5;

// Remember postings we already sent (workflow static data, kept 60 days).
// Note: static data is only saved in production (scheduled) runs, not in manual test runs.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
for (const k of Object.keys(store.seen)) if (Date.now() - Date.parse(store.seen[k]) > 60 * 864e5) delete store.seen[k];

const jobs = new Map();
$input.all().forEach((item, idx) => {
  for (const p of (item.json && item.json.ergebnisliste) || []) {
    const ref = p.referenznummer;
    if (!ref || store.seen[ref]) continue;
    // The API ignores the "published since" parameter, so filter by date here.
    const ts = Math.max(Date.parse(p.datumErsteVeroeffentlichung || '') || 0, Date.parse(p.aenderungsdatum || '') || 0);
    if (ts < cutoff) continue;
    const title = p.stellenangebotsTitel || '';
    if (excludeRe && excludeRe.test(title + ' ' + (p.hauptberuf || ''))) continue;
    const prev = jobs.get(ref);
    if (prev) { prev.matched.add(queries[idx]); continue; }
    const adr = ((p.stellenlokationen || [])[0] || {}).adresse || {};
    jobs.set(ref, {
      ref, title, company: p.firma || '', city: adr.ort || '',
      distanceKm: typeof p.entfernung === 'number' ? p.entfernung : null,
      homeOffice: !!p.homeofficemoeglich, published: p.datumErsteVeroeffentlichung || '',
      url: p.externeURL || ('https://www.arbeitsagentur.de/jobsuche/jobdetail/' + ref),
      matched: new Set([queries[idx]]),
    });
  }
});

// Simple ranking: more matching keywords first, then keyword in title, home office, distance.
const ranked = [...jobs.values()].map(j => {
  const inTitle = [...j.matched].some(k => new RegExp('(^|[^\\p{L}])' + k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '($|[^\\p{L}])', 'iu').test(j.title));
  const score = j.matched.size * 10 + (inTitle ? 15 : 0) + (j.homeOffice ? 5 : 0) - (j.distanceKm || 0) / 10;
  return { ...j, matched: [...j.matched], score: Math.round(score) };
}).sort((a, b) => b.score - a.score);

// Everything found today counts as seen, so lower-ranked leftovers do not trickle in tomorrow.
for (const j of ranked) store.seen[j.ref] = new Date().toISOString();
const top = ranked.slice(0, Number(s.maxJobsInDigest || 15));
return top.map(j => ({ json: { ...j, totalFound: ranked.length } }));

// Build one Telegram message (HTML). Long digests are split below Telegram's 4096-char limit.
const s = $('Search settings').first().json;
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const today = new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', day: '2-digit', month: '2-digit', year: 'numeric' }).format(new Date());
const blocks = $input.all().map(({ json: j }) =>
  `<b>${esc(j.title)}</b>\n${esc(j.company)} · ${esc(j.city)}${j.distanceKm != null ? ' · ' + j.distanceKm + ' km' : ''}${j.homeOffice ? ' · 🏠 Homeoffice' : ''}\n`
  + `🔎 ${esc(j.matched.join(', '))}\n<a href="${esc(j.url)}">Stellenanzeige öffnen</a>`);
const total = $input.first().json.totalFound;
const header = `🧭 <b>Neue Stellen ${today}</b> — ${total} Treffer rund um ${esc(s.location)} (${s.radiusKm} km)`
  + (total > blocks.length ? `, hier die ${blocks.length} besten` : '');
const parts = [];
let cur = header;
for (const b of blocks) {
  if ((cur + '\n\n' + b).length > 3800) { parts.push(cur); cur = b; } else cur += '\n\n' + b;
}
parts.push(cur);
return parts.map(text => ({ json: { text, chatId: s.telegramChatId } }));
